mapper.select:
SELECT YEAR(a.create_time) AS `year`, a.license_device_name AS deviceName, COUNT(*) AS count FROM biz_license_original a LEFT JOIN biz_license_duplicate d ON a.id = d.original_id LEFT JOIN biz_application b ON a.application_id = b.id LEFT JOIN biz_institution_ext c ON b.institution_id = c.dept_id WHERE a.deleted = 0 AND d.acceptance_status = 1
AND a.license_device_name IN
#{item}
AND c.city = #{req.region}
GROUP BY YEAR(a.create_time), a.license_device_name ORDER BY `year`

SELECT c.city AS region, COUNT(*) AS count FROM biz_license_original a LEFT JOIN biz_license_duplicate d ON a.id = d.original_id LEFT JOIN biz_application b ON a.application_id = b.id LEFT JOIN biz_institution_ext c ON b.institution_id = c.dept_id WHERE a.deleted = 0 AND d.acceptance_status = 1
AND a.license_device_name = #{deviceName}
AND c.city = #{req.region}
GROUP BY c.city ORDER BY count DESC

SELECT CASE WHEN c.region IS NULL OR c.region = '' THEN '市本级' ELSE c.region END AS county, COUNT(*) AS count FROM biz_license_original a LEFT JOIN biz_license_duplicate d ON a.id = d.original_id LEFT JOIN biz_application b ON a.application_id = b.id LEFT JOIN biz_institution_ext c ON b.institution_id = c.dept_id WHERE a.deleted = 0 AND d.acceptance_status = 1
AND a.license_device_name = #{deviceName}
AND c.city = #{region}
AND c.city = #{req.region}
GROUP BY CASE WHEN c.region IS NULL OR c.region = '' THEN '市本级' ELSE c.region END ORDER BY count DESC

SELECT c.institution_name AS institutionName, COUNT(*) AS count FROM biz_license_original a LEFT JOIN biz_license_duplicate d ON a.id = d.original_id LEFT JOIN biz_application b ON a.application_id = b.id LEFT JOIN biz_institution_ext c ON b.institution_id = c.dept_id WHERE a.deleted = 0 AND d.acceptance_status = 1
AND a.license_device_name = #{deviceName}
AND c.city = #{region}
AND c.region = #{county}
AND (c.region IS NULL OR c.region = '')
GROUP BY c.institution_name ORDER BY count DESC

select a.city, a.institution_name, b.license_device_name, b.ladder_config_model,
       b.license_no, b.issue_date, c.installation_date, c.production_enterprise,
       c.specific_model, c.duplicate_issue_date, b.status
from biz_application d
left join biz_institution_ext a on d.institution_id = a.dept_id
left join biz_license_original b on b.application_id = d.id
left join biz_license_duplicate c on b.id = c.original_id
where d.app_status = 5 and d.app_type in (1, 5) and b.deleted = 0 and c.deleted = 0

    and d.ladder_config_model = #{req.ladderConfigModel}


    and a.city = #{req.region}


    and c.acceptance_status = #{req.acceptanceStatus}


    and a.institution_type = 1


    and a.institution_type in (2, 3, 4)


    and YEAR(b.create_time) = #{req.year}


    and YEAR(b.create_time) between #{req.startDate} and #{req.endDate}


    and b.license_device_name in

        #{item}



    and b.status = #{req.status}


    and (a.institution_name like concat('%', #{req.keywords}, '%')
    or b.license_no like concat('%', #{req.keywords}, '%')
         )

SELECT count(b.id) as num, a.city, b.license_device_name, case when a.institution_type = 1 then '社会办医' else '政府办医' END AS institution_type_label, SUM(CASE WHEN d.acceptance_status = 1 THEN 1 ELSE 0 END) as accepted, SUM(CASE WHEN d.acceptance_status = 0 THEN 1 ELSE 0 END) as not_accepted FROM biz_institution_ext a LEFT JOIN biz_application b ON a.dept_id = b.institution_id left join biz_license_original c on b.id = c.application_id left join biz_license_duplicate d on c.id = d.original_id where b.app_status = 5 and b.deleted = 0
and a.city = #{req.region}
and a.city in ('铜川市', '渭南市', '安康市', '商洛市', '延安市', '榆林市')
and b.license_device_name in
#{item}
and c.acceptance_status = #{req.acceptanceStatus}
and a.institution_type = 1
and a.institution_type in (2, 3, 4)
GROUP BY a.region, b.license_device_name

SELECT b.name AS institutionName, COUNT(DISTINCT a.id) AS count FROM history_license a LEFT JOIN history_dept b ON a.pzdwmc = b.duns LEFT JOIN history_area e ON a.sbpzdzCode = e.id LEFT JOIN history_area city ON city.id = CASE WHEN e.levelx = 3 THEN e.pid ELSE e.id END
b.name IS NOT NULL
AND city.name = #{region}
AND e.levelx = 3 AND e.name = #{county}
AND e.levelx = 2
GROUP BY b.name ORDER BY count DESC
